"""P&L rollup engine: aggregate GL leaf postings up the chart-of-accounts tree.

Produces, per month:
  * a nested dict mirroring coa.json (internal nodes carry a "total" key,
    leaves are floats), and
  * a flat monthly P&L (indented rows) renderable as text.
"""
import csv
import json
from pathlib import Path


class UnmappedAccountError(ValueError):
    """Raised when a GL line references an account code absent from the COA."""

    def __init__(self, code, row_num=None):
        self.code = code
        msg = f"Unmapped account code: {code!r}"
        if row_num is not None:
            msg += f" (gl line {row_num})"
        super().__init__(msg)


# ---------------------------------------------------------------- COA helpers

def load_coa(path):
    return json.loads(Path(path).read_text())


def iter_leaves(node):
    if "code" in node:
        yield node
    for child in node.get("children", []):
        yield from iter_leaves(child)


def build_index(coa):
    """Map account code -> tuple of node names from below the root to the leaf."""
    index = {}

    def walk(node, trail):
        if "code" in node:
            index[node["code"]] = tuple(trail)
            return
        for child in node["children"]:
            walk(child, trail + [child["name"]])

    walk(coa, [])
    return index


# ---------------------------------------------------------------- aggregation

def _empty_tree(node):
    """Tree skeleton with zeros: leaves are 0.0, internal nodes are dicts."""
    if "code" in node:
        return 0.0
    out = {"total": 0.0}
    for child in node["children"]:
        out[child["name"]] = _empty_tree(child)
    return out


def _add(tree_children, path_names, amount):
    """Add amount to the leaf at path_names, rolling into every ancestor total."""
    node = tree_children
    for name in path_names[:-1]:
        node = node[name]
        node["total"] += amount
    node[path_names[-1]] += amount
    tree_children["total"] += amount


def build_rollup(gl_path, coa_path):
    """Return {"monthly": {month: nested_tree}, "grand_total": float}."""
    coa = load_coa(coa_path)
    index = build_index(coa)
    root_name = coa["name"]

    monthly = {}
    grand_total = 0.0

    with open(gl_path, newline="") as f:
        for row_num, row in enumerate(csv.DictReader(f), start=2):
            code = (row.get("account_code") or "").strip()
            if not code:
                raise UnmappedAccountError("<missing>", row_num)
            if code not in index:
                raise UnmappedAccountError(code, row_num)
            amount = float(row["amount"])
            month = row["month"]
            tree = monthly.setdefault(month, {root_name: _empty_tree(coa)})
            _add(tree[root_name], index[code], amount)
            grand_total += amount

    return {"monthly": monthly, "grand_total": grand_total}


# ---------------------------------------------------------------- flat P&L

def flatten(monthly_tree):
    """Depth-first rows of (depth, label, amount) from a {root: subtree} dict."""
    (name, subtree), = monthly_tree.items()
    rows = []

    def walk(label, node, depth):
        if isinstance(node, (int, float)):
            rows.append((depth, label, node))
            return
        rows.append((depth, label, node["total"]))
        for key, value in node.items():
            if key != "total":
                walk(key, value, depth + 1)

    walk(name, subtree, 0)
    return rows


def format_pnl(rollup, month):
    """Render one month's P&L as pinned text."""
    lines = [f"P&L - {month}", "=" * 60]
    for depth, label, amount in flatten({k: v for k, v in rollup["monthly"][month].items()}):
        lines.append(f"{'  ' * depth}{label:<42}{amount:>15,.2f}")
    lines.append("=" * 60)
    return "\n".join(lines)


def net_income(monthly_tree):
    (subtree,), = [v["total"] for v in monthly_tree.values()] and [(monthly_tree[next(iter(monthly_tree))],)]
    return subtree["total"]


if __name__ == "__main__":
    r = build_rollup("gl.csv", "coa.json")
    for m in sorted(r["monthly"]):
        print(format_pnl(r, m))
        print()

